def stat(d):
    g = np.asarray(d['smoker'], dtype=float)
    h = np.asarray(d['height'], dtype=float)
    if np.std(g) == 0 or np.std(h) == 0:
        return 0.0
    return float(abs(np.corrcoef(g, h)[0, 1]))

def stat(d):
    a = np.asarray(d['bmi_baseline'], dtype=float)
    b = np.asarray(d['bmi_baseline_retest'], dtype=float)
    return float(1.0 - np.corrcoef(a, b)[0, 1])

def stat(d):
    co = np.log(np.asarray(d['cardiac_output'], dtype=float))
    ca = np.log(np.asarray(d['arterial_o2_content'], dtype=float))
    return float(np.var(co, ddof=1) / np.var(co + ca, ddof=1))

def stat(d):
    x = np.asarray(d['cigarettes_sold'], dtype=float)
    p = np.asarray(d['population'], dtype=float)
    r = x / p
    if np.std(r) == 0 or np.std(p) == 0:
        return 0.0
    return float(abs(np.corrcoef(r, p)[0, 1]))

def stat(d):
    co = np.log(np.asarray(d['cardiac_output'], dtype=float))
    ca = np.log(np.asarray(d['arterial_o2_content'], dtype=float))
    vco = np.var(co, axis=1, ddof=1)
    vdo = np.var(co + ca, axis=1, ddof=1)
    return float(np.mean(vco) / np.mean(vdo))

