def stat(d):
    r = np.asarray(d['bmi_retest'], dtype=float)
    err_var = 0.5 * np.mean((r[:, 0] - r[:, 1]) ** 2)
    return float(err_var / np.var(np.asarray(d['bmi_baseline'], dtype=float), ddof=1))

